using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Register a named HttpClient for WeatherTools.
// The MCP SDK resolves WeatherTools from DI; the HttpClient is injected
// automatically because AddHttpClient<T> registers T as a transient service
// whose HttpClient instance is managed by IHttpClientFactory.
builder.Services.AddHttpClient<WeatherTools>();

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()       // communicate over stdin/stdout
    .WithToolsFromClass<WeatherTools>();  // register all [McpServerTool] methods

await builder.Build().RunAsync();

